(()=>{const rail=document.querySelector('.assembly-grid');if(!rail)return;const cards=[...rail.children],prev=document.querySelector('[data-assembly-prev]'),next=document.querySelector('[data-assembly-next]'),label=document.querySelector('[data-assembly-position]');let current=0;const sync=()=>{current=Math.max(0,Math.min(cards.length-1,Math.round(rail.scrollLeft/(cards[0].getBoundingClientRect().width+parseFloat(getComputedStyle(rail).gap||0)))));label.textContent=`Step ${current+1} of ${cards.length}`;prev.disabled=current===0;next.disabled=current===cards.length-1};const move=delta=>{const i=Math.max(0,Math.min(cards.length-1,current+delta));rail.scrollTo({left:i*(cards[0].getBoundingClientRect().width+parseFloat(getComputedStyle(rail).gap||0)),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})};prev.addEventListener('click',()=>move(-1));next.addEventListener('click',()=>move(1));rail.addEventListener('scroll',sync,{passive:true});rail.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();move(e.key==='ArrowRight'?1:-1)}});window.addEventListener('resize',sync);sync()})();
